import Foundation

struct Budget {
    var limit: Decimal
    var spent: Decimal = 0
}

extension Budget: CustomStringConvertible {
    var remaining: Decimal { limit - spent }
    var description: String { "\(spent) of \(limit) spent" }

    func record(_ amount: Decimal) { spent += amount }
}

var food = Budget(limit: 300)
food.record(42)
print(food)
